```python
def verify_username(name_input: str) -> bool:
    if len(name_input) > 255:
        return False
    try:
        # Replace literal '%' with encoded form '%25' so unquote can handle it correctly
        # But note: input may already contain percent-encoded sequences like '%61', replacement would corrupt them
        # Therefore, a better method is: first attempt decoding, if decoding fails due to invalid percent-encoding, then check if the original input contains only allowed characters
        # But this is complex. Simplified solution: use unquote with errors='ignore' option, ignoring invalid percent-encodings
        canonicalized = urllib.parse.unquote(name_input, errors='ignore')
        allowed_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789%')
        for char in canonicalized:
            if char not in allowed_chars:
                return False
        return True
    except Exception:
